use std::path::PathBuf;

use crate::config::settings::Settings;
use crate::toolset::tool_version::ResolveOptions;

#[derive(Debug, Clone)]
pub(crate) struct InstallOptions {
    pub reason: String,
    pub force: bool,
    pub jobs: Option<usize>,
    pub raw: bool,
    /// only install missing tools if passed as arguments
    pub missing_args_only: bool,
    /// install lazy declarations because the user explicitly named a tool
    pub include_lazy: bool,
    /// completely disable auto-installation when auto_install setting is false
    pub skip_auto_install: bool,
    pub auto_install_disable_tools: Option<Vec<String>>,
    pub resolve_options: ResolveOptions,
    pub dry_run: bool,
    /// Only run hooks defined in global config files.
    pub global_hooks_only: bool,
    /// require lockfile URLs to be present; fail if not
    pub locked: bool,
    /// Override the install directory (e.g. for --system or --shared)
    pub install_dir: Option<PathBuf>,
    /// Derive each tool's install directory from the scope of the config file that
    /// declares it. Lazy first-use dispatch installs a provider together with its
    /// dependencies, and those can come from different scopes.
    pub scoped_install_dirs: bool,
    /// skip confirmation prompts (e.g. installing missing plugin system deps).
    /// Defaults to the global `yes` setting; `mise bootstrap --yes` also sets it.
    pub yes: bool,
}

impl Default for InstallOptions {
    fn default() -> Self {
        InstallOptions {
            jobs: Some(Settings::get().jobs),
            raw: Settings::get().raw,
            reason: "install".to_string(),
            force: false,
            missing_args_only: true,
            include_lazy: false,
            skip_auto_install: false,
            auto_install_disable_tools: Settings::get().auto_install_disable_tools.clone(),
            resolve_options: Default::default(),
            dry_run: false,
            global_hooks_only: false,
            locked: Settings::get().locked,
            install_dir: None,
            scoped_install_dirs: false,
            yes: Settings::get().yes,
        }
    }
}
    pub(crate) async fn install_all_versions_with_progress(
        &mut self,
        config: &mut Arc<Config>,
        mut versions: Vec<ToolRequest>,
        opts: &InstallOptions,
        progress: Option<Box<dyn InstallProgress>>,
    ) -> Result<Vec<ToolVersion>> {
        if versions.is_empty() {
            // Configured plugins are still installed when no tools need work
            // (for example, env-only plugins).
            Self::ensure_config_plugins_installed(config, opts.dry_run).await?;
            return Ok(vec![]);
        }

        self.init_request_options(&mut versions);
        ensure_compatible_install_requests(&versions)?;
        ensure_safe_install_options(&versions)?;

        // Validate shared install destinations before plugin installation or
        // hooks introduce side effects.
        Self::ensure_config_plugins_installed(config, opts.dry_run).await?;

        // Initialize a footer for the entire install session once (before batching)
        let mpr = MultiProgressReport::get();
        let footer_reason = if opts.dry_run {
            format!("{} (dry-run)", opts.reason)
        } else {
            opts.reason.clone()
        };
        let mut install_progress = progress.or_else(|| {
            (!opts.raw && !opts.dry_run)
                .then(|| {
                    install_progress(
                        &mpr,
                        versions.iter().map(|tr| (tool_key(tr), tr.to_string())),
                    )
                })
                .flatten()
        });
        if install_progress.is_none() {
            mpr.init_footer(opts.dry_run, &footer_reason, versions.len());
        }

        hooks::run_one_hook_with_context(
            config,
            self,
            Hooks::Preinstall,
            None,
            None,
            opts.dry_run,
            opts.global_hooks_only,
        )
        .await;

        show_python_install_hint(&versions);

        let mut disabled_backend_errors = vec![];
        versions.retain(|tr| {
            if let Ok(backend) = tr.backend()
                && let Err(err) = backend::ensure_backend_enabled(&backend.get_type())
            {
                    );
                }
            }
            if self.dry_run_code {
                return Err(exit::request(1));
            }
            return Ok(());
        }

        let opts = InstallOptions {
            reason: "upgrade".to_string(),
            force: false,
            jobs: self.jobs,
            raw: self.raw,
            resolve_options: ResolveOptions {
                use_locked_version: false,
                latest_versions: true,
                resolve_rolling_channels: false,
                prefer_exact_version: false,
                before_date,
                before_date_from_default: false,
                filter_installed_versions_by_release_date: false,
                offline: false,
                refresh_remote_versions: false,
                inactive: self.inactive,
            },
            locked: false,
            ..Default::default()
        };

        // Preserve the storage scope of an existing system install while upgrading it.
        // Equal user/system roots classify as local, so they intentionally take the
        // ordinary path and are never scanned or installed twice.
        let (system_outdated, user_outdated): (Vec<_>, Vec<_>) =
            outdated.iter().partition(|outdated| {
                env::install_path_category(&outdated.tool_version.install_path())
                    == env::InstallPathCategory::System
            });
        let user_requests = user_outdated
            .into_iter()
            .map(|outdated| outdated.tool_request.clone())
            .collect::<Vec<_>>();
