#!/usr/bin/env bash

printf 'dummy 1\ntiny 1\n' >.tool-versions
mise install dummy@1.0.0 tiny@1.0.0 >/dev/null 2>&1 || fail "pre-install of dummy@1.0.0 failed"

output="$(MISE_FORCE_PROGRESS=1 mise up 2>&1)"
summary_line="  dummy 1.0.0 → 1.1.0"

if [[ $output != *"$summary_line"* ]]; then
  fail "upgrade summary did not include '$summary_line': $output"
fi

after_summary="${output#*"$summary_line"}"
if grep -q $'\033\\[[0-9;]*J' <<<"$after_summary"; then
  fail "upgrade summary was followed by a terminal clear sequence"
fi

# Lookup/install sessions leave the richer upgrade summary as the only success
# record. Deferred pruning is one notice, independent of the tool count.
plain=$(printf '%s' "$output" | sed -E $'s/\\x1b\\[[0-9;?]*[a-zA-Z]//g')
assert_contains 'printf "%s" "$plain"' 'tiny 1.0.0 → 1.1.0'
assert_contains 'printf "%s" "$plain"' '2 old versions will be pruned after 24h'
assert_not_contains 'printf "%s" "$plain"' '✓ dummy'
assert_not_contains 'printf "%s" "$plain"' '✓ tiny'
assert_not_contains 'printf "%s" "$plain"' 'resolved 2 tools'
assert_not_contains 'printf "%s" "$plain"' 'installed 2 tools'
assert_not_contains 'printf "%s" "$plain"' 'dummy@1.0.0 will be pruned'
