# Portable timeout helper for e2e tests.
# Uses system timeout/gtimeout when available, otherwise falls back to a
# shell implementation that returns 124 on timeout.
run_with_timeout() {
  local seconds="$1"
  shift

  local output_file
  output_file="$(mktemp)"

  ("$@" >"$output_file" 2>&1) &
  local cmd_pid=$!
  local elapsed=0
  local timed_out=0

  while kill -0 "$cmd_pid" 2>/dev/null; do
    if ((elapsed >= seconds * 10)); then
      timed_out=1
      kill -TERM "$cmd_pid" 2>/dev/null || true
      sleep 0.2
      kill -KILL "$cmd_pid" 2>/dev/null || true
      wait "$cmd_pid" 2>/dev/null || true
      break
    fi
    sleep 0.1
    elapsed=$((elapsed + 1))
  done

  local exit_status=0
  if ((timed_out == 1)); then
    exit_status=124
  else
    wait "$cmd_pid" || exit_status=$?
  fi

  cat "$output_file"
  rm -f "$output_file"
  return "$exit_status"
}

parse_timeout_seconds() {
  local duration="$1"
  if [[ ! $duration =~ ^[0-9]+[smh]?$ ]]; then
    return 1
  fi
  case "$duration" in
    *s)
      echo "${duration%s}"
      ;;
    *m)
      echo $((10#${duration%m} * 60))
      ;;
    *h)
      echo $((10#${duration%h} * 3600))
      ;;
    *)
      echo $((10#$duration))
      ;;
  esac
}

